mapper.select:
SELECT a.usr_id, a.usr_eml, a.usr_pwd, a.usr_nm, a.usr_phn_no, a.usr_lst_log_dt, a.usr_acct_sts_cd, a.cre_usr_id, a.cre_dt, a.upd_usr_id, a.upd_dt, STRING_AGG(c.role_cd, ',' ORDER BY c.role_cd) AS usr_roles, count(*) over() AS ttl_no, count(*) over() + 1 - ROW_NUMBER() over(
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.usr_id
) as no FROM usr_mgmt a LEFT JOIN usr_role_mgmt b ON a.usr_id = b.usr_id LEFT JOIN role_mgmt c ON b.role_id = c.role_id WHERE a.usr_acct_sts_cd = 'A' AND ( c.role_cd != 'ADM' OR c.role_cd IS NULL )
AND UPPER(a.usr_nm) LIKE #{usrNm}
AND UPPER(a.usr_eml) LIKE #{usrEml}
GROUP BY a.usr_id, a.usr_eml, a.usr_pwd, a.usr_nm, a.usr_phn_no, a.usr_lst_log_dt, a.usr_acct_sts_cd, a.cre_usr_id, a.cre_dt, a.upd_usr_id, a.upd_dt
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.usr_id
OFFSET ${offset}
LIMIT ${limit}

mapper.update:
	UPDATE usr_mgmt
    SET usr_lst_log_dt = #{usrLstLoginDt}
    WHERE usr_id = #{usrId}

UPDATE usr_mgmt
SET usr_acct_sts_cd = 'D'
WHERE usr_id = #{usrId}

		UPDATE usr_mgmt
        SET 
        	usr_pwd = #{usrPwd},
        	upd_usr_id = #{updUsrId},
        	upd_dt = #{updDt}
        WHERE usr_id = #{usrId}
